head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70014";
scwin.obj = undefined;
scwin.rtnVal = "";
scwin.chkArrNo = undefined;
scwin.chkTitle = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "iframe_2", attr: "src", fn: function () { return "/discls/searchDisclosureDocument.do?method=srchSubmitDoc4RelDiscls&tgtIsurCd=" + String(String((dma_pageContext.get("tgtIsurCd") ?? ""))); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        blockLoading();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70014.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.chkArrNo =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods70014' }); }

try { scwin.chkTitle =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods70014' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70014.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_nonSelect_onclick
 * @description 「-|-」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_nonSelect_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.noSelected(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70014.ipt_nonSelect_onclick' }); }
};

/**
 * @method
 * @name btn_selected_onclick
 * @description 「선택」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selected_onclick = async function(e){
    try {
        await scwin.selected()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70014.btn_selected_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70014.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dataLoading
 * @description data Loading 처리
 * @returns {void}
 * @hidden N
 */
scwin.dataLoading = function () {
    blockLoading();
};

/**
 * @method
 * @name hideLoading
 * @description hide Loading 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideLoading = function () {
    ($.fn && $.fn.dialog ? $("#loading").dialog("close") : undefined);
};

/**
 * @method
 * @name checkIt
 * @description check It 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.checkIt = function (ver) {
    scwin.obj = (document.form || { elements: [] });
    const subObj = document.iframe.searchForm.relDiscl;
    const nonSelectObj = $c.util.getComponent('ipt_nonSelect');
    let tmpVal = null;
    let arrLength = 0;
    const arrNo = ((ver.value).split("|"))[0];
    scwin.resetRtnVal(arrNo);
    if ((String(nonSelectObj.getValue() || "") !== "") === true) {
        scwin.chkArrNo = [];
        scwin.chkTitle = [];
        nonSelectObj.checked = false;
    }
    if (scwin.chkArrNo.length !== 0) {
        arrLength = scwin.chkArrNo.length;
    }
    if (ver.checked === true) {
        tmpVal = (ver.value).split("|");
        scwin.chkArrNo[arrLength] = tmpVal[0];
        scwin.chkTitle[arrLength] = tmpVal[1];
    }
    scwin.rtnVal = scwin.chkArrNo.join(",") + "|" + scwin.chkArrNo.join("\n");
    (($c.util.getComponent("txt_docs")) && ($c.util.getComponent("txt_docs")).setValue ? ($c.util.getComponent("txt_docs")).setValue(scwin.chkTitle.join("<br/>")) : (($c.util.getComponent("txt_docs")) ? (($c.util.getComponent("txt_docs")).innerHTML = scwin.chkTitle.join("<br/>")) : void (scwin.chkTitle.join("<br/>"))));
};

/**
 * @method
 * @name resetRtnVal
 * @description reset Rtn Val 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.resetRtnVal = function (ver) {
    const tmpArr1 = [];
    const tmpArr2 = [];
    let cnt = 0;
    for (let i = 0; i < scwin.chkArrNo.length; i++) {
        if (scwin.chkArrNo[i] !== ver) {
            tmpArr1[cnt] = scwin.chkArrNo[i];
            tmpArr2[cnt] = scwin.chkTitle[i];
            cnt++;
        }
    }
    scwin.chkArrNo = [];
    scwin.chkTitle = [];
    scwin.chkArrNo = tmpArr1;
    scwin.chkTitle = tmpArr2;
};

/**
 * @method
 * @name selected
 * @description selected 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selected = async function () {
    const chkObj = (document.formCheck || { elements: [] });
    let isChoice = false;
    const subObj = document.iframe.searchForm.relDiscl;
    if (scwin.chkArrNo.length !== 0) {
        isChoice = true;
    }
    if (((String($c.util.getComponent('ipt_nonSelect').getValue() || "") !== "")) || isChoice) {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setSelectedData === 'function' ? (scwin.openerScwin()).fn_setSelectedData('' + dma_pageContext.get("formKey") + '', '' + dma_pageContext.get("formKey") + '', decodeURIComponent('' + dma_pageContext.get("returnKey") + ''), scwin.chkArrNo.join(","), scwin.chkTitle.join("\n")) : void 0), $c.win.closePopup(['' + dma_pageContext.get("formKey") + '', '' + dma_pageContext.get("formKey") + '', decodeURIComponent('' + dma_pageContext.get("returnKey") + ''), scwin.chkArrNo.join(","), scwin.chkTitle.join("\n")]));
        $c.win.closePopup();
    } else {
        await $c.win.alert("해당사항이 없는 경우 '해당없음'을 체크 하십시오!");
    }
};

/**
 * @method
 * @name noSelected
 * @description no Selected 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.noSelected = function (ver) {
    scwin.obj = (document.form || { elements: [] });
    const subObj = document.iframe.searchForm.relDiscl;
    if (ver.checked === true) {
        if (subObj.value !== '') {
            for (let i = 0; i < subObj.relDiscl.length; i++) {
                subObj.relDiscl[i].checked = false;
            }
        }
        $c.util.getComponent('txt_docs').setLabel("");
        scwin.chkArrNo = [];
        scwin.chkTitle = [];
        scwin.chkArrNo[0] = '-';
        scwin.chkTitle[0] = '-';
    } else {
        scwin.chkArrNo = [];
        scwin.chkTitle = [];
    }
};

/**
 * @method
 * @name setCheckedCheckBox
 * @description set Checked Check Box 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.setCheckedCheckBox = function (ver) {
    const subObj = document.iframe.searchForm.relDiscl;
    let tmpVal = null;
    if (ver !== 0) {
        if (scwin.chkArrNo.length !== 0) {
            for (let i = 0; i < scwin.chkArrNo.length; i++) {
                for (let k = 0; k < subObj.relDiscl.length; k++) {
                    tmpVal = (subObj.relDiscl[k].value).split("|");
                    if (scwin.chkArrNo[i] === tmpVal[0]) {
                        subObj.relDiscl[k].checked = true;
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
